using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with reflection-based metadata for all types.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver(),
    WriteIndented    = true
};

// ── 1. Strongly-typed retrieval: GetTypeInfo<T>() ──────────────
// Returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata for Person — Type: {personInfo.Type.Name}");

var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine(json);

// ── 2. Probe without throwing: TryGetTypeInfo() ────────────────
// Returns false instead of throwing when metadata isn't available.
// Use a resolver that knows about *nothing* to simulate the "not found" case.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { static ti =>
        {
            // Reject every type except string (artificial limitation).
            if (ti.Type != typeof(string))
                throw new NotSupportedException();
        }}
    }
};

bool found = limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo for Person on limited resolver — found: {found}, info: {info?.Type.Name ?? "(null)"}");

found = limited.TryGetTypeInfo(typeof(string), out info);
Console.WriteLine($"TryGetTypeInfo for string  on limited resolver — found: {found}, info: {info?.Type.Name ?? "(null)"}");

// Same probe on the full resolver — succeeds.
found = options.TryGetTypeInfo(typeof(Person), out info);
Console.WriteLine($"TryGetTypeInfo for Person on full resolver    — found: {found}, info: {info?.Type.Name ?? "(null)"}");

record Person(string Name, int Age);

