/// <summary>Resolver that only provides metadata for <see cref="string"/>.</summary>
sealed class OnlyStringResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) =>
        type == typeof(string)
            ? JsonMetadataServices.CreateValueInfo<string>(options, JsonMetadataServices.StringConverter)
            : null;          // returning null ⇒ TryGetTypeInfo returns false
}
